class Solution {
  public int maxDistance(java.util.List<java.util.List<Integer>> arrays) {
    int answer = 0, min = arrays.get(0).get(0), max = arrays.get(0).get(arrays.get(0).size() - 1);
    for (int i = 1; i < arrays.size(); i++) {
      java.util.List<Integer> a = arrays.get(i);
      int first = a.get(0), last = a.get(a.size() - 1);
      answer = Math.max(answer, Math.max(last - min, max - first));
      min = Math.min(min, first);
      max = Math.max(max, last);
    }
    return answer;
  }
}
